messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Dusk Flats — Straight Sprint</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#141519;}
  canvas{position:fixed;inset:0;display:block;touch-action:none;cursor:grab;}
  canvas:active{cursor:grabbing;}
  #hud{position:fixed;inset:0;pointer-events:none;color:#f2ede2;
       font-family:ui-monospace,"SF Mono","Cascadia Mono",Menlo,Consolas,"Liberation Mono",monospace;
       -webkit-user-select:none;user-select:none;}
  .panel{position:absolute;background:rgba(10,12,16,.55);border:1px solid rgba(242,237,226,.16);
         border-radius:8px;padding:10px 14px;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);}
  .micro{font-size:10px;font-weight:600;letter-spacing:.22em;text-transform:uppercase;opacity:.6;white-space:nowrap;}
  .tl{top:16px;left:18px;}
  .tl .row{display:flex;align-items:center;gap:12px;margin-top:7px;}
  .lap{font-size:11px;font-weight:700;letter-spacing:.16em;border:1px solid rgba(242,237,226,.28);border-radius:4px;padding:3px 8px;}
  .clock{font-size:25px;font-weight:700;letter-spacing:.05em;font-variant-numeric:tabular-nums;line-height:1;}
  .tc{top:16px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;
      font-size:12px;font-weight:700;letter-spacing:.14em;white-space:nowrap;}
  .dot{width:9px;height:9px;border-radius:50%;background:#98917f;flex:none;}
  .bl{left:18px;bottom:18px;width:190px;}
  .br{right:18px;bottom:18px;width:190px;text-align:right;}
  .br .bar i{margin-left:auto;}
  .spd{font-size:30px;font-weight:700;line-height:1.15;font-variant-numeric:tabular-nums;}
  .spd .unit{font-size:11px;font-weight:600;letter-spacing:.14em;opacity:.55;margin-left:6px;}
  .bar{height:3px;background:rgba(242,237,226,.14);border-radius:2px;margin-top:8px;overflow:hidden;display:flex;}
  .bar i{display:block;height:100%;width:0%;border-radius:2px;}
  #flash{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%) scale(.94);
         font-size:clamp(30px,5.6vw,58px);font-weight:700;letter-spacing:.14em;white-space:nowrap;
         color:#f6efe2;text-shadow:0 2px 22px rgba(10,8,6,.55),0 1px 3px rgba(10,8,6,.5);
         opacity:0;transition:opacity .16s ease,transform .16s ease;}
  #flash.show{opacity:1;transform:translate(-50%,-50%) scale(1);}
  #flash.win{color:#ff6a55;}
  #hint{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);font-size:10px;font-weight:600;
        letter-spacing:.22em;opacity:.5;transition:opacity 1.2s;white-space:nowrap;}
  #hint.off{opacity:0;}
  #vig{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 46%,transparent 55%,rgba(9,7,8,.4) 100%);}
  #fade{position:fixed;inset:0;background:#0c0d11;opacity:0;pointer-events:none;transition:opacity .45s ease;}
  #fade.on{opacity:1;}
  @media (max-width:760px){
    .bl,.br{width:150px;padding:8px 11px;}
    .spd{font-size:24px;}
    .clock{font-size:20px;}
    .tc{top:auto;bottom:118px;}
  }
</style>
</head>
<body>
<div id="hud">
  <div id="vig"></div>
  <div class="panel tl">
    <div class="micro">Dusk Flats · Straight Sprint</div>
    <div class="row"><span class="lap" id="lap">LAP 01</span><span class="clock" id="clock">00:00.00</span></div>
  </div>
  <div class="panel tc"><span class="dot" id="leadDot"></span><span id="leadTxt">GRID LOCKED</span></div>
  <div class="panel bl">
    <div class="micro" style="color:#ff6a58;opacity:.95">Red Car · №07</div>
    <div class="spd"><span id="kmhR">0</span><span class="unit">km/h</span></div>
    <div class="bar"><i id="barR" style="background:#ff4b3c"></i></div>
  </div>
  <div class="panel br">
    <div class="micro" style="color:#7fa4ff;opacity:.95">Blue Car · №21</div>
    <div class="spd"><span id="kmhB">0</span><span class="unit">km/h</span></div>
    <div class="bar"><i id="barB" style="background:#5c8dff"></i></div>
  </div>
  <div id="flash"></div>
  <div id="hint">Drag to orbit · Scroll to zoom</div>
</div>
<div id="fade"></div>

<script type="module">
import * as THREE from './three.module.js';

/* ---------------- renderer / scene / camera ---------------- */
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xdd9358, 130, 560);
const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 2200);

/* ---------------- canvas texture helper ---------------- */
function tex(w,h,draw){
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  draw(c.getContext('2d'),w,h);
  const t=new THREE.CanvasTexture(c);
  t.colorSpace=THREE.SRGBColorSpace;
  t.anisotropy=8;
  return t;
}

/* ---------------- dusk sky (procedural dome + sun) ---------------- */
const sunDir = new THREE.Vector3(-0.5,0.26,-0.83).normalize();
const skyMat = new THREE.ShaderMaterial({
  side:THREE.BackSide, depthWrite:false, fog:false,
  uniforms:{
    cTop:{value:new THREE.Color(0x27384a)},
    cHor:{value:new THREE.Color(0xe89a55)},
    cSun:{value:new THREE.Color(0xffd9a8)},
    sunDir:{value:sunDir}
  },
  vertexShader:`
    varying vec3 vDir;
    void main(){ vDir=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
  fragmentShader:`
    varying vec3 vDir;
    uniform vec3 cTop; uniform vec3 cHor; uniform vec3 cSun; uniform vec3 sunDir;
    void main(){
      vec3 d=normalize(vDir);
      float h=clamp(d.y,0.0,1.0);
      vec3 col=mix(cHor,cTop,pow(smoothstep(0.0,0.6,h),0.9));
      col+=cHor*0.22*pow(1.0-h,4.0);
      float bel=1.0-smoothstep(-0.08,0.02,d.y);
      col=mix(col,cHor*1.05,bel);
      float s=clamp(dot(d,sunDir),0.0,1.0);
      col+=cSun*(pow(s,220.0)*1.1+pow(s,10.0)*0.30+pow(s,2.5)*0.10);
      col+=cSun*smoothstep(0.9992,0.99965,s)*1.4;
      gl_FragColor=vec4(col,1.0);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }`
});
scene.add(new THREE.Mesh(new THREE.SphereGeometry(1000,32,18), skyMat));

/* environment reflections for the car paint, captured from the same sky */
{
  const pmrem=new THREE.PMREMGenerator(renderer);
  const envScene=new THREE.Scene();
  envScene.add(new THREE.Mesh(new THREE.SphereGeometry(60,24,12), skyMat));
  scene.environment=pmrem.fromScene(envScene,0.04).texture;
  pmrem.dispose();
}

/* ---------------- lights ---------------- */
const sun=new THREE.DirectionalLight(0xffc290,3.0);
sun.castShadow=true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.near=40; sun.shadow.camera.far=280;
sun.shadow.camera.left=-36; sun.shadow.camera.right=36;
sun.shadow.camera.top=36; sun.shadow.camera.bottom=-36;
sun.shadow.camera.updateProjectionMatrix();
sun.shadow.bias=-0.0006; sun.shadow.normalBias=0.03;
scene.add(sun); scene.add(sun.target);
scene.add(new THREE.HemisphereLight(0x93a7c4,0x8a7457,0.55));
const fill=new THREE.DirectionalLight(0xaebfd8,0.55);
fill.position.set(60,40,80);
scene.add(fill);

/* ---------------- constants ---------------- */
const FINISH=420, TRACK_W=14, LANE_R=-2.2, LANE_B=2.2;

/* ---------------- ground ---------------- */
const groundTex=tex(512,512,(g,w,h)=>{
  g.fillStyle='#9b8a73'; g.fillRect(0,0,w,h);
  for(let i=0;i<9000;i++){
    g.fillStyle=Math.random()<0.5?'rgba(58,48,36,0.10)':'rgba(238,222,190,0.09)';
    g.fillRect(Math.random()*w,Math.random()*h,1+Math.random()*2,1+Math.random()*2);
  }
  for(let i=0;i<26;i++){
    const x=Math.random()*w,y=Math.random()*h,r=24+Math.random()*70;
    const gr=g.createRadialGradient(x,y,0,x,y,r);
    gr.addColorStop(0,'rgba(74,62,46,0.12)'); gr.addColorStop(1,'rgba(74,62,46,0)');
    g.fillStyle=gr; g.beginPath(); g.arc(x,y,r,0,7); g.fill();
  }
});
groundTex.wrapS=groundTex.wrapT=THREE.RepeatWrapping;
groundTex.repeat.set(70,70);
const ground=new THREE.Mesh(
  new THREE.PlaneGeometry(2600,2600).rotateX(-Math.PI/2),
  new THREE.MeshStandardMaterial({map:groundTex,roughness:1,metalness:0})
);
ground.receiveShadow=true;
scene.add(ground);

/* ---------------- track (asphalt strip with lane markings) ---------------- */
const trackTex=tex(1024,512,(g,w,h)=>{
  g.fillStyle='#41444a'; g.fillRect(0,0,w,h);
  for(let i=0;i<7000;i++){
    g.fillStyle=Math.random()<0.5?'rgba(18,19,22,0.16)':'rgba(210,212,216,0.07)';
    g.fillRect(Math.random()*w,Math.random()*h,1+Math.random()*2,1+Math.random()*1.6);
  }
  for(const vy of [0.343,0.657]){                       // tyre wear in each lane
    for(let i=0;i<60;i++){
      g.fillStyle='rgba(16,17,20,'+(0.05+Math.random()*0.09).toFixed(3)+')';
      g.fillRect(Math.random()*w, vy*h-16+Math.random()*20, 30+Math.random()*90, 14+Math.random()*26);
    }
  }
  g.fillStyle='#ded8ca';                                // edge lines
  g.fillRect(0,12,w,9); g.fillRect(0,h-21,w,9);
  for(let x=0;x<w;x+=307) g.fillRect(x,h/2-4,150,8);    // centre dashes (20 m per tile)
});
trackTex.wrapS=trackTex.wrapT=THREE.RepeatWrapping;
const TRACK_L=720, TRACK_X0=-70;
trackTex.repeat.set(TRACK_L/20,1);
const track=new THREE.Mesh(
  new THREE.PlaneGeometry(TRACK_L,TRACK_W).rotateX(-Math.PI/2),
  new THREE.MeshStandardMaterial({map:trackTex,roughness:0.94,metalness:0})
);
track.position.set(TRACK_X0+TRACK_L/2,0.02,0);
track.receiveShadow=true;
scene.add(track);

/* ---------------- checkered start line ---------------- */
function checkerTex(cols,rows,a='#ece7db',b='#17191d'){
  return tex(cols*24,rows*24,(g,w,h)=>{
    for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
      g.fillStyle=(r+c)%2?a:b; g.fillRect(c*24,r*24,24,24);
    }
  });
}
const startLine=new THREE.Mesh(
  new THREE.PlaneGeometry(2.6,TRACK_W).rotateX(-Math.PI/2),
  new THREE.MeshStandardMaterial({map:checkerTex(5,22),roughness:0.85})
);
startLine.position.set(0,0.045,0);
startLine.receiveShadow=true;
scene.add(startLine);

/* ---------------- finish gantry ---------------- */
const gantry=new THREE.Group();
const pylonMat=new THREE.MeshStandardMaterial({color:0x1e2126,roughness:0.6,metalness:0.35});
for(const s of [-1,1]){
  const p=new THREE.Mesh(new THREE.BoxGeometry(0.75,7.4,0.75),pylonMat);
  p.position.set(FINISH,3.7,s*8.1); p.castShadow=true; gantry.add(p);
}
const beam=new THREE.Mesh(new THREE.BoxGeometry(0.85,0.95,17.2),pylonMat);
beam.position.set(FINISH,7.05,0); beam.castShadow=true; gantry.add(beam);

const bannerTex=tex(1024,208,(g,w,h)=>{
  g.fillStyle='#14161a'; g.fillRect(0,0,w,h);
  const cell=26;
  for(let r=0;r<2;r++)for(let c=0;c<w/cell;c++){
    g.fillStyle=(r+c)%2?'#eee9dc':'#191b1f';
    g.fillRect(c*cell,r*cell,cell,cell);
    g.fillRect(c*cell,h-(r+1)*cell,cell,cell);
  }
  g.fillStyle='#f2ede1'; g.textAlign='center'; g.textBaseline='middle';
  g.font='700 76px ui-monospace, Menlo, Consolas, monospace';
  g.fillText('F I N I S H',w/2,h/2+2);
});
const bannerMat=new THREE.MeshStandardMaterial({map:bannerTex,roughness:0.8});
for(const s of [1,-1]){
  const b=new THREE.Mesh(new THREE.PlaneGeometry(16.4,2.5),bannerMat);
  b.position.set(FINISH,5.55,s*0.46);
  if(s<0) b.rotation.y=Math.PI;
  gantry.add(b);
}
scene.add(gantry);

/* ---------------- distance marker boards ---------------- */
function boardTex(txt){
  return tex(256,176,(g,w,h)=>{
    g.fillStyle='#191c22'; g.fillRect(0,0,w,h);
    g.strokeStyle='rgba(240,234,222,0.55)'; g.lineWidth=6; g.strokeRect(9,9,w-18,h-18);
    g.fillStyle='#efe9db'; g.textAlign='center'; g.textBaseline='middle';
    g.font='700 82px ui-monospace, Menlo, Consolas, monospace';
    g.fillText(txt,w/2,h/2+4);
  });
}
const postMatD=new THREE.MeshStandardMaterial({color:0x2a2d33,roughness:0.7,metalness:0.3});
for(const d of [100,200,300,400]){
  const t=boardTex(String(d));
  for(const s of [-1,1]){
    const post=new THREE.Mesh(new THREE.BoxGeometry(0.14,2.4,0.14),postMatD);
    post.position.set(d,1.2,s*9.6); post.castShadow=true; scene.add(post);
    const panel=new THREE.Mesh(new THREE.PlaneGeometry(2.1,1.45),
      new THREE.MeshStandardMaterial({map:t,roughness:0.8}));
    panel.position.set(d,2.85,s*9.6);
    scene.add(panel);
  }
}

/* ---------------- white edge posts (parallax speed cue) ---------------- */
{
  const xs=[];
  for(let x=-40;x<=640;x+=26){ if(x>FINISH-40&&x<FINISH+14) continue; xs.push(x); }
  const posts=new THREE.InstancedMesh(
    new THREE.CylinderGeometry(0.07,0.09,0.9,8),
    new THREE.MeshStandardMaterial({color:0xe8e3d5,roughness:0.7}),
    xs.length*2
  );
  const m4=new THREE.Matrix4(); let pi=0;
  for(const x of xs)for(const s of [-1,1]){ m4.makeTranslation(x,0.45,s*7.55); posts.setMatrixAt(pi++,m4); }
  posts.instanceMatrix.needsUpdate=true;
  posts.castShadow=true;
  scene.add(posts);
}

/* ---------------- checkered kerbs flanking the finish ---------------- */
{
  const kerbA=new THREE.MeshStandardMaterial({color:0xded8ca,roughness:0.85});
  const kerbB=new THREE.MeshStandardMaterial({color:0xc23b2c,roughness:0.85});
  const kerbGeo=new THREE.BoxGeometry(2.1,0.1,0.62);
  for(let i=0;i<21;i++){
    const x=FINISH-34+i*2.1;
    for(const s of [-1,1]){
      const k=new THREE.Mesh(kerbGeo,i%2?kerbA:kerbB);
      k.position.set(x+1.05,0.06,s*7.32);
      k.castShadow=true; k.receiveShadow=true;
      scene.add(k);
    }
  }
}

/* ---------------- distant mesas + scattered rocks ---------------- */
{
  const mA=new THREE.MeshStandardMaterial({color:0x77665a,roughness:1,flatShading:true});
  const mB=new THREE.MeshStandardMaterial({color:0x84715f,roughness:1,flatShading:true});
  const mesa=(x,z,r,h,alt)=>{
    const m=new THREE.Mesh(new THREE.ConeGeometry(r,h,5,1),alt?mB:mA);
    m.position.set(x,h/2-2,z);
    m.rotation.y=Math.random()*Math.PI;
    m.scale.x=1+Math.random()*0.6;
    scene.add(m);
  };
  mesa(-260,-420,150,95,0); mesa(-60,-360,110,70,1); mesa(180,-460,170,110,0);
  mesa(430,-380,120,78,1);  mesa(660,-440,160,100,0); mesa(880,-350,110,66,1);
  mesa(300,430,140,88,1);   mesa(-150,400,120,72,0); mesa(760,470,150,92,1);

  const rockMat=new THREE.MeshStandardMaterial({color:0x6f604f,roughness:1,flatShading:true});
  for(let i=0;i<30;i++){
    const r=new THREE.Mesh(new THREE.IcosahedronGeometry(0.6+Math.random()*1.5,0),rockMat);
    const side=Math.random()<0.5?-1:1;
    r.position.set(-60+Math.random()*720,0.1,side*(13+Math.random()*55));
    r.scale.set(1+Math.random()*1.4,0.5+Math.random()*0.7,1+Math.random()*1.4);
    r.rotation.y=Math.random()*7;
    r.castShadow=true; r.receiveShadow=true;
    scene.add(r);
  }
}

/* ---------------- the two race cars ---------------- */
function taperBox(w,h,d,fn){
  const g=new THREE.BoxGeometry(w,h,d);
  const p=g.attributes.position;
  for(let i=0;i<p.count;i++){
    const v=fn(p.getX(i),p.getY(i),p.getZ(i));
    p.setXYZ(i,v[0],v[1],v[2]);
  }
  g.computeVertexNormals();
  return g;
}
function roundelTex(txt){
  return tex(128,128,(g)=>{
    g.beginPath(); g.arc(64,64,56,0,7);
    g.fillStyle='#f4efe2'; g.fill();
    g.lineWidth=7; g.strokeStyle='#1a1c20'; g.stroke();
    g.fillStyle='#1a1c20'; g.textAlign='center'; g.textBaseline='middle';
    g.font='700 54px ui-monospace, Menlo, Consolas, monospace';
    g.fillText(txt,64,67);
  });
}
function buildCar(paint,num){
  const car=new THREE.Group();
  const body=new THREE.Group();      // pitches/bobs independently of the wheels
  car.add(body);
  const paintMat=new THREE.MeshStandardMaterial({color:paint,metalness:0.35,roughness:0.3});
  const darkMat=new THREE.MeshStandardMaterial({color:0x1b1d21,metalness:0.3,roughness:0.7});
  const glassMat=new THREE.MeshStandardMaterial({color:0x121820,metalness:0.7,roughness:0.16});
  const accentMat=new THREE.MeshStandardMaterial({color:0xf3eee1,metalness:0.2,roughness:0.5});

  const add=(geo,mat,x,y,z,rz=0)=>{
    const m=new THREE.Mesh(geo,mat);
    m.position.set(x,y,z); m.rotation.z=rz;
    m.castShadow=true;
    body.add(m);
    return m;
  };

  add(new THREE.BoxGeometry(4.3,0.52,1.84),paintMat,0,0.55,0);                          // chassis
  add(taperBox(1.5,0.42,1.6,(x,y,z)=>x>0?[x,y*0.5-0.08,z*0.72]:[x,y,z]),paintMat,2.3,0.52,0);   // wedge nose
  add(taperBox(1.7,0.55,1.34,(x,y,z)=>y>0?[x*0.78-0.1,y,z*0.58]:[x,y,z]),glassMat,0.1,1.06,0);  // canopy
  add(new THREE.BoxGeometry(1.5,0.3,1.7),paintMat,-1.4,0.96,0);                          // engine deck
  add(new THREE.BoxGeometry(0.62,0.08,2.0),darkMat,-2.45,1.3,0,0.12);                    // rear wing
  add(new THREE.BoxGeometry(0.56,0.36,0.06),darkMat,-2.45,1.2,1.0);                      // endplates
  add(new THREE.BoxGeometry(0.56,0.36,0.06),darkMat,-2.45,1.2,-1.0);
  add(new THREE.BoxGeometry(0.09,0.42,0.09),darkMat,-2.36,1.02,0.4);                     // struts
  add(new THREE.BoxGeometry(0.09,0.42,0.09),darkMat,-2.36,1.02,-0.4);
  add(new THREE.BoxGeometry(0.7,0.08,1.7),darkMat,2.78,0.3,0);                           // splitter
  add(new THREE.BoxGeometry(4.2,0.035,0.32),accentMat,0,0.828,0);                        // accent stripes
  add(new THREE.BoxGeometry(1.4,0.035,0.32),accentMat,-1.4,1.12,0);

  const headMat=new THREE.MeshStandardMaterial({color:0xfff6e0,emissive:0xffd9a0,emissiveIntensity:2.4});
  const tailMat=new THREE.MeshStandardMaterial({color:0x30090a,emissive:0xff2416,emissiveIntensity:1.8});
  add(new THREE.BoxGeometry(0.1,0.12,0.3),headMat,3.02,0.44,0.4);
  add(new THREE.BoxGeometry(0.1,0.12,0.3),headMat,3.02,0.44,-0.4);
  add(new THREE.BoxGeometry(0.08,0.11,0.36),tailMat,-2.18,0.62,0.6);
  add(new THREE.BoxGeometry(0.08,0.11,0.36),tailMat,-2.18,0.62,-0.6);

  const rMat=new THREE.MeshStandardMaterial({map:roundelTex(num),transparent:true,roughness:0.55,metalness:0});
  const r1=new THREE.Mesh(new THREE.PlaneGeometry(0.72,0.72),rMat);
  r1.position.set(0.35,0.62,0.935); body.add(r1);
  const r2=r1.clone(); r2.position.z=-0.935; r2.rotation.y=Math.PI; body.add(r2);

  const tireMat=new THREE.MeshStandardMaterial({color:0x141518,roughness:0.92});
  const hubMat=new THREE.MeshStandardMaterial({color:0xc9ccd2,metalness:0.85,roughness:0.3,flatShading:true});
  const tireGeo=new THREE.CylinderGeometry(0.42,0.42,0.34,22).rotateX(Math.PI/2);
  const hubGeo=new THREE.CylinderGeometry(0.21,0.21,0.36,6).rotateX(Math.PI/2);
  const wheels=[];
  for(const wx of [1.55,-1.55])for(const wz of [0.88,-0.88]){
    const w=new THREE.Group();
    const t=new THREE.Mesh(tireGeo,tireMat); t.castShadow=true;
    w.add(t,new THREE.Mesh(hubGeo,hubMat));
    w.position.set(wx,0.42,wz);
    car.add(w); wheels.push(w);
  }
  scene.add(car);
  return {car,body,wheels,phase:Math.random()*7};
}
const redCar=buildCar(0xe33024,'07');
const blueCar=buildCar(0x2b6ff2,'21');

/* ---------------- soft dust/smoke sprites ---------------- */
const puffTex=tex(64,64,(g)=>{
  const gr=g.createRadialGradient(32,32,2,32,32,30);
  gr.addColorStop(0,'rgba(255,255,255,0.85)');
  gr.addColorStop(0.5,'rgba(255,255,255,0.4)');
  gr.addColorStop(1,'rgba(255,255,255,0)');
  g.fillStyle=gr; g.fillRect(0,0,64,64);
});
const POOL=70, puffs=[];
for(let i=0;i<POOL;i++){
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:puffTex,color:0xb5a797,transparent:true,opacity:0,depthWrite:false}));
  s.visible=false; scene.add(s);
  puffs.push({s,life:0,max:1,vel:new THREE.Vector3(),grow:2,peak:0.3,active:false});
}
let puffCursor=0, smokeAcc=0;
function spawnPuff(x,y,z,str){
  const p=puffs[puffCursor++%POOL];
  p.active=true; p.life=0; p.max=0.6+Math.random()*0.6;
  p.s.position.set(x+(Math.random()-0.5)*0.4,y,z+(Math.random()-0.5)*0.4);
  p.vel.set(-1-Math.random()*2.5,0.7+Math.random()*1.3,(Math.random()-0.5)*1.4);
  p.grow=1.6+Math.random()*1.6;
  p.peak=0.16+0.22*str;
  p.s.scale.setScalar(0.5+Math.random()*0.5);
  p.s.visible=true;
}
function updatePuffs(dt){
  for(const p of puffs){
    if(!p.active) continue;
    p.life+=dt;
    if(p.life>=p.max){ p.active=false; p.s.visible=false; p.s.material.opacity=0; continue; }
    p.s.position.addScaledVector(p.vel,dt);
    p.vel.multiplyScalar(Math.exp(-dt*1.4));
    p.vel.y+=0.55*dt;
    p.s.scale.addScalar(p.grow*dt);
    p.s.material.opacity=Math.sin(Math.PI*p.life/p.max)*p.peak;
  }
}

/* ---------------- HUD refs & flash ---------------- */
const $=id=>document.getElementById(id);
const elClock=$('clock'), elLap=$('lap'), elLeadDot=$('leadDot'), elLeadTxt=$('leadTxt'),
      elKR=$('kmhR'), elKB=$('kmhB'), elBR=$('barR'), elBB=$('barB'),
      flashEl=$('flash'), fadeEl=$('fade'), hintEl=$('hint');
let flashTimer=0;
function flash(txt,cls,hold){
  flashEl.textContent=txt;
  flashEl.className=cls||'';
  void flashEl.offsetWidth;
  flashEl.classList.add('show');
  clearTimeout(flashTimer);
  flashTimer=setTimeout(()=>flashEl.classList.remove('show'),hold);
}
setTimeout(()=>hintEl.classList.add('off'),6500);

/* ---------------- race state machine ---------------- */
/* Blue launches harder and leads early; red builds speed through the mid-race,
   overtakes around 55% distance and takes the flag. Then rollout -> reset -> loop. */
const sm=(a,b,x)=>{x=Math.min(1,Math.max(0,(x-a)/(b-a)));return x*x*(3-2*x);};
const speedRed =t=>(20+16*(1-Math.exp(-t/3.1)))*(1-Math.exp(-t/0.32));
const speedBlue=t=>(26+5*(1-Math.exp(-t/0.8)))*(1-Math.exp(-t/0.32))-3*sm(8,13,t);

let state='count', stT=0, clockT=0, lap=1, countStep=-1, resetDone=false;
let xr=0, xb=0, vr=0, vb=0, pvR=0, pvB=0, accR=0, accB=0;
let overtakeT=0, fovKick=0, prevDiff=0;

/* ---------------- camera: cinematic chase + user orbit ---------------- */
let camYaw=0, camPitch=0, camZoom=1, lastPointer=-10, dragging=false, lpx=0, lpy=0;
const cvs=renderer.domElement;
cvs.addEventListener('pointerdown',e=>{
  dragging=true; lpx=e.clientX; lpy=e.clientY; lastPointer=elapsed;
  cvs.setPointerCapture(e.pointerId);
});
cvs.addEventListener('pointermove',e=>{
  if(!dragging) return;
  camYaw-=(e.clientX-lpx)*0.0042;
  camPitch+=(e.clientY-lpy)*0.0032;
  camYaw=Math.max(-1.35,Math.min(1.35,camYaw));
  camPitch=Math.max(-0.24,Math.min(0.8,camPitch));
  lpx=e.clientX; lpy=e.clientY; lastPointer=elapsed;
});
addEventListener('pointerup',()=>dragging=false);
addEventListener('pointercancel',()=>dragging=false);
cvs.addEventListener('wheel',e=>{
  e.preventDefault();
  camZoom=Math.max(0.5,Math.min(2.4,camZoom*Math.exp(e.deltaY*0.0011)));
  lastPointer=elapsed;
},{passive:false});
addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

/* ---------------- main loop ---------------- */
const clock=new THREE.Clock();
let elapsed=0, smMid=0, smGap=0, smLook=0, fov=50;

function animate(){
  requestAnimationFrame(animate);
  const dt=Math.min(clock.getDelta(),0.05);
  elapsed+=dt;
  stT+=dt;

  /* ----- race logic ----- */
  if(state==='count'){
    const step=Math.min(3,Math.floor(stT/0.75));
    if(step!==countStep){
      countStep=step;
      if(step<3) flash(String(3-step),'',650);
      else flash('GO','',800);
    }
    if(stT>=2.62){ state='run'; stT=0; clockT=0; }
  }else if(state==='run'){
    clockT+=dt;
    pvR=vr; pvB=vb;
    vr=speedRed(clockT); vb=speedBlue(clockT);
    accR+=(((vr-pvR)/Math.max(dt,1e-4))-accR)*(1-Math.exp(-dt*5));
    accB+=(((vb-pvB)/Math.max(dt,1e-4))-accB)*(1-Math.exp(-dt*5));
    xr+=vr*dt; xb+=vb*dt;
    const diff=xr-xb;
    if(prevDiff<0&&diff>=0){ overtakeT=0.8; fovKick=4.5; }   // the pass: punch in + tyre haze
    prevDiff=diff;
    if(xr>=FINISH){
      state='fin'; stT=0;
      const margin=xr-xb;
      const tg=margin/Math.max(vb,6);
      fovKick=Math.max(fovKick,3.5);
      flash('RED WINS  +'+tg.toFixed(2)+' S','win',2700);
    }
  }else if(state==='fin'){
    pvR=vr; pvB=vb;
    vr*=Math.exp(-dt*1.5); vb*=Math.exp(-dt*1.5);
    if(vr<0.25)vr=0; if(vb<0.25)vb=0;
    accR+=(((vr-pvR)/Math.max(dt,1e-4))-accR)*(1-Math.exp(-dt*5));
    accB+=(((vb-pvB)/Math.max(dt,1e-4))-accB)*(1-Math.exp(-dt*5));
    xr+=vr*dt; xb+=vb*dt;
    if(stT>2.9){ state='reset'; stT=0; resetDone=false; fadeEl.classList.add('on'); }
  }else if(state==='reset'){
    if(stT>0.55&&!resetDone){
      resetDone=true; lap++;
      xr=xb=0; vr=vb=0; accR=accB=0; clockT=0; countStep=-1; prevDiff=0;
      elLap.textContent='LAP '+String(lap).padStart(2,'0');
    }
    if(stT>0.98){ fadeEl.classList.remove('on'); state='count'; stT=0; }
  }

  /* ----- cars: position, wheel spin, squat/bob ----- */
  redCar.car.position.set(xr,0,LANE_R);
  blueCar.car.position.set(xb,0,LANE_B);
  for(const w of redCar.wheels) w.rotation.z-=(vr/0.42)*dt;
  for(const w of blueCar.wheels) w.rotation.z-=(vb/0.42)*dt;
  redCar.body.rotation.z=THREE.MathUtils.clamp(accR*0.006,-0.05,0.055);
  blueCar.body.rotation.z=THREE.MathUtils.clamp(accB*0.006,-0.05,0.055);
  const bobAmp=Math.min(1,(vr+vb)/40);
  if(state==='count'){
    redCar.body.position.y=Math.sin(elapsed*31)*0.006+Math.sin(elapsed*47+1)*0.004;
    blueCar.body.position.y=Math.sin(elapsed*27+2)*0.006+Math.sin(elapsed*43)*0.004;
  }else{
    redCar.body.position.y=Math.sin(elapsed*9+redCar.phase)*0.012*bobAmp;
    blueCar.body.position.y=Math.sin(elapsed*9+blueCar.phase)*0.012*bobAmp;
  }

  /* ----- dust: launch, hard acceleration, overtake burst, braking ----- */
  if(state==='run'||state==='fin'){
    let rate=0;
    if(state==='run'){
      if(clockT<1.1) rate=75;
      if(accR>3.2) rate=Math.max(rate,30);
      if(accB>3.2) rate=Math.max(rate,30);
    }else if(vr>6||vb>6){ rate=16; }
    if(overtakeT>0){ rate=Math.max(rate,55); overtakeT-=dt; }
    smokeAcc+=rate*dt;
    while(smokeAcc>1){
      smokeAcc-=1;
      const c=Math.random()<0.5?redCar:blueCar;
      const v=c===redCar?vr:vb;
      if(v>1) spawnPuff(c.car.position.x-1.6,0.22,c.car.position.z+(Math.random()<0.5?0.88:-0.88),Math.min(1,v/30));
    }
  }
  updatePuffs(dt);

  /* ----- camera framing: follow both cars, widen with their gap ----- */
  const mid=(xr+xb)/2, gap=Math.abs(xr-xb), avg=(vr+vb)/2;
  smMid+=(mid-smMid)*(1-Math.exp(-dt*3.4));
  smGap+=(gap-smGap)*(1-Math.exp(-dt*2.2));
  smLook+=(Math.min(14,avg*0.34)-smLook)*(1-Math.exp(-dt*2.6));
  if(elapsed-lastPointer>3.5){                     // gently return to the broadcast angle
    camYaw*=Math.exp(-dt*1.4);
    camPitch*=Math.exp(-dt*1.4);
    camZoom+=(1-camZoom)*(1-Math.exp(-dt*1.4));
  }
  fovKick*=Math.exp(-dt*2.1);
  const closeness=1-sm(2.5,7,gap);
  const fovT=50-7*closeness-fovKick;
  fov+=(fovT-fov)*(1-Math.exp(-dt*5));
  if(Math.abs(fov-camera.fov)>0.01){ camera.fov=fov; camera.updateProjectionMatrix(); }

  const aspect=innerWidth/innerHeight;
  const phi=THREE.MathUtils.clamp(0.38+camPitch,0.14,1.15);
  const tanH=Math.tan(THREE.MathUtils.degToRad(fov)*0.5)*aspect;
  let R=(27.5+smGap*0.28)*camZoom;
  R*=Math.max(1,1.45/aspect);
  R=Math.max(R,(smGap*0.5+5.5)/Math.max(0.05,tanH*Math.cos(phi)));
  R=Math.min(R,95);
  const tx=smMid+smLook, ty=1.15;
  camera.position.set(
    tx+R*Math.cos(phi)*Math.sin(camYaw),
    ty+R*Math.sin(phi),
    R*Math.cos(phi)*Math.cos(camYaw)
  );
  camera.lookAt(tx,ty,0);

  /* ----- sun + shadow frustum follow the action ----- */
  sun.position.set(smMid+sunDir.x*150,sunDir.y*150,sunDir.z*150);
  sun.target.position.set(smMid,0,0);

  /* ----- HUD ----- */
  const mm=Math.floor(clockT/60), ss=Math.floor(clockT%60), cs=Math.floor((clockT*100)%100);
  elClock.textContent=String(mm).padStart(2,'0')+':'+String(ss).padStart(2,'0')+'.'+String(cs).padStart(2,'0');
  const diff=xr-xb;
  if(state==='count'||state==='reset'){ elLeadTxt.textContent='GRID LOCKED'; elLeadDot.style.background='#98917f'; }
  else if(Math.abs(diff)<0.5){ elLeadTxt.textContent='NECK AND NECK'; elLeadDot.style.background='#cfc7b4'; }
  else if(diff>0){ elLeadTxt.textContent='RED +'+diff.toFixed(1)+' M'; elLeadDot.style.background='#ff4b3c'; }
  else{ elLeadTxt.textContent='BLUE +'+(-diff).toFixed(1)+' M'; elLeadDot.style.background='#5c8dff'; }
  elKR.textContent=Math.round(vr*3.6);
  elKB.textContent=Math.round(vb*3.6);
  elBR.style.width=Math.min(100,vr/40*100)+'%';
  elBB.style.width=Math.min(100,vb/40*100)+'%';

  renderer.render(scene,camera);
}
animate();
